import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import {
  extractUninstallDetails,
  sendShopifyUninstallEmail,
} from "../_shared/shopify-uninstall-email.ts";
import { verifyShopifyWebhook } from "../_shared/shopify-webhook-verify.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers":
    "Content-Type, Authorization, X-Client-Info, Apikey, X-Shopify-Hmac-Sha256, X-Shopify-Topic, X-Shopify-Shop-Domain, X-Shopify-Welcome-Email-Secret",
};

type ManualUninstallBody = {
  shop_domain?: string;
  shop_name?: string;
  shop_email?: string;
  country_code?: string;
  locale?: "pt" | "es" | "en";
  force?: boolean;
};

function jsonResponse(body: Record<string, unknown>, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

async function enrichFromDatabase(
  details: NonNullable<ReturnType<typeof extractUninstallDetails>>,
) {
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  const { data } = await supabase
    .from("shopify_welcome_emails")
    .select("shop_contact_email, shop_country_code")
    .eq("shop_domain", details.shopDomain)
    .maybeSingle();

  if (!details.shopEmail && data?.shop_contact_email) {
    details.shopEmail = data.shop_contact_email;
  }
  if (!details.countryCode && data?.shop_country_code) {
    details.countryCode = data.shop_country_code;
  }

  if (!details.shopName || details.shopName === details.shopDomain) {
    const { data: shopRow } = await supabase
      .from("shopify_shops")
      .select("shop_contact_email, shop_country_code")
      .eq("shop_domain", details.shopDomain)
      .maybeSingle();

    if (!details.shopEmail && shopRow?.shop_contact_email) {
      details.shopEmail = shopRow.shop_contact_email;
    }
    if (!details.countryCode && shopRow?.shop_country_code) {
      details.countryCode = shopRow.shop_country_code;
    }
  }

  return details;
}

async function processUninstall(
  shopDomainHeader: string | null,
  payload: Record<string, unknown>,
) {
  let details = extractUninstallDetails(shopDomainHeader, payload);
  if (!details) {
    console.warn("[shopify-app-uninstalled] missing shop domain or email");
    return;
  }

  details = await enrichFromDatabase(details);

  if (!details.shopEmail) {
    console.warn("[shopify-app-uninstalled] no email for", details.shopDomain);
    return;
  }

  const result = await sendShopifyUninstallEmail(details);
  console.log("[shopify-app-uninstalled] result:", result);
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const rawBody = await req.text();

  const manualSecret = Deno.env.get("SHOPIFY_WELCOME_EMAIL_SECRET")?.trim();
  const headerSecret = req.headers.get("X-Shopify-Welcome-Email-Secret")?.trim();
  if (manualSecret && headerSecret === manualSecret) {
    let body: ManualUninstallBody;
    try {
      body = JSON.parse(rawBody) as ManualUninstallBody;
    } catch {
      return jsonResponse({ error: "Invalid JSON body" }, 400);
    }

    if (!body.shop_domain || !body.shop_name || !body.shop_email) {
      return jsonResponse({
        error: "shop_domain, shop_name, and shop_email are required",
      }, 400);
    }

    try {
      const result = await sendShopifyUninstallEmail({
        shopDomain: body.shop_domain,
        shopName: body.shop_name,
        shopEmail: body.shop_email,
        countryCode: body.country_code,
        locale: body.locale,
        force: body.force,
      });
      return jsonResponse(result);
    } catch (error) {
      return jsonResponse({
        error: error instanceof Error ? error.message : "Failed to send uninstall email",
      }, 500);
    }
  }

  const shopifySecret = Deno.env.get("SHOPIFY_API_SECRET")?.trim();
  const hmac = req.headers.get("X-Shopify-Hmac-Sha256");

  if (!shopifySecret) {
    console.error("[shopify-app-uninstalled] SHOPIFY_API_SECRET not configured");
    return new Response("Server misconfigured", { status: 500 });
  }

  if (!await verifyShopifyWebhook(rawBody, hmac, shopifySecret)) {
    return new Response("Unauthorized", { status: 401 });
  }

  const topic = req.headers.get("X-Shopify-Topic");
  if (topic !== "app/uninstalled") {
    return jsonResponse({ received: true, ignored: true, topic });
  }

  let payload: Record<string, unknown> = {};
  try {
    payload = JSON.parse(rawBody) as Record<string, unknown>;
  } catch {
    return jsonResponse({ error: "Invalid webhook payload" }, 400);
  }

  const shopDomain = req.headers.get("X-Shopify-Shop-Domain");
  EdgeRuntime.waitUntil(processUninstall(shopDomain, payload));

  return jsonResponse({ received: true });
});

import { createClient } from "jsr:@supabase/supabase-js@2";
import { localeFromCountryCode } from "./locale-from-country.ts";
import { buildUninstallEmail } from "./shopify-uninstall-templates.ts";
import { sendZohoEmail } from "./zoho-mail.ts";

export type UninstallEmailInput = {
  shopDomain: string;
  shopName: string;
  shopEmail: string;
  countryCode?: string | null;
  locale?: "pt" | "es" | "en";
  force?: boolean;
};

export type UninstallEmailResult = {
  ok: boolean;
  skipped: boolean;
  reason?: string;
  locale?: string;
  message_id?: string;
  sent_at?: string;
};

export async function sendShopifyUninstallEmail(
  input: UninstallEmailInput,
): Promise<UninstallEmailResult> {
  const shopDomain = input.shopDomain.trim().toLowerCase();
  const shopName = input.shopName.trim();
  const shopEmail = input.shopEmail.trim().toLowerCase();

  if (!shopDomain || !shopName || !shopEmail) {
    throw new Error("shopDomain, shopName, and shopEmail are required");
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  const { data: existingSend, error: lookupError } = await supabase
    .from("shopify_uninstall_emails")
    .select("sent_at")
    .eq("shop_domain", shopDomain)
    .maybeSingle();

  if (lookupError) {
    throw new Error("Failed to lookup uninstall email record");
  }

  if (existingSend?.sent_at && !input.force) {
    return {
      ok: true,
      skipped: true,
      reason: "already_sent",
      sent_at: existingSend.sent_at,
    };
  }

  const locale = input.locale ?? localeFromCountryCode(input.countryCode);
  const emailContent = buildUninstallEmail(locale, shopName);
  const messageId = await sendZohoEmail({
    toAddress: shopEmail,
    subject: emailContent.subject,
    htmlContent: emailContent.html,
    textContent: emailContent.text,
  });

  const sentAt = new Date().toISOString();
  const countryCode = input.countryCode?.trim().toUpperCase() ?? null;

  await supabase.from("shopify_uninstall_emails").upsert(
    {
      shop_domain: shopDomain,
      shop_contact_email: shopEmail,
      shop_country_code: countryCode,
      locale,
      zoho_message_id: messageId,
      sent_at: sentAt,
    },
    { onConflict: "shop_domain" },
  );

  // Permite reenviar boas-vindas se a loja reinstalar depois.
  await supabase.from("shopify_welcome_emails").delete().eq("shop_domain", shopDomain);

  await supabase
    .from("shopify_shops")
    .update({
      billing_status: "cancelled",
      updated_at: sentAt,
    })
    .eq("shop_domain", shopDomain);

  return {
    ok: true,
    skipped: false,
    locale,
    message_id: messageId,
    sent_at: sentAt,
  };
}

export function extractUninstallDetails(
  shopDomainHeader: string | null,
  payload: Record<string, unknown>,
): UninstallEmailInput | null {
  const shopDomain = (
    shopDomainHeader ||
    (typeof payload.myshopify_domain === "string" ? payload.myshopify_domain : "") ||
    (typeof payload.domain === "string" ? payload.domain : "")
  ).trim().toLowerCase();

  const shopName = (
    typeof payload.name === "string" ? payload.name : shopDomain
  ).trim();

  const shopEmail = (
    (typeof payload.customer_email === "string" ? payload.customer_email : "") ||
    (typeof payload.email === "string" ? payload.email : "")
  ).trim().toLowerCase();

  const countryCode =
    typeof payload.country_code === "string" ? payload.country_code : null;

  if (!shopDomain || !shopEmail) return null;

  return { shopDomain, shopName, shopEmail, countryCode };
}

import type { WelcomeLocale } from "./locale-from-country.ts";

export type UninstallEmailContent = {
  subject: string;
  html: string;
  text: string;
};

const SUPPORT_EMAIL = "contato@omafit.co";

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export function buildUninstallEmail(
  locale: WelcomeLocale,
  shopName: string,
): UninstallEmailContent {
  const copy = {
    pt: {
      subject: "Sentimos sua saída do Omafit — podemos conversar?",
      greeting: `Olá, equipe da ${shopName}!`,
      intro:
        "Notamos que o Omafit foi desinstalado da sua loja Shopify. Antes de você seguir em frente, gostaríamos de entender o que aconteceu.",
      ask:
        "O que motivou a desinstalação? Foi a configuração, o resultado do provador virtual, o preço ou outro ponto? Uma linha já ajuda muito.",
      offer:
        "Se ainda fizer sentido, podemos conversar e tentar resolver juntos — às vezes é algo simples de ajustar.",
      reply: "Basta responder este e-mail. Estamos à disposição.",
      signOff: "Obrigado pelo tempo com o Omafit,\nEquipe Omafit",
    },
    es: {
      subject: "Lamentamos tu salida de Omafit — ¿podemos hablar?",
      greeting: `¡Hola, equipo de ${shopName}!`,
      intro:
        "Notamos que desinstalaste Omafit de tu tienda Shopify. Antes de que sigas adelante, nos gustaría entender qué ocurrió.",
      ask:
        "¿Qué te llevó a desinstalar? ¿Fue la configuración, los resultados del probador virtual, el precio u otro motivo? Con una línea nos ayudas mucho.",
      offer:
        "Si todavía tiene sentido, podemos conversar e intentar resolverlo juntos — a veces es algo sencillo de ajustar.",
      reply: "Solo responde a este correo. Estamos disponibles.",
      signOff: "Gracias por el tiempo con Omafit,\nEquipo Omafit",
    },
    en: {
      subject: "Sorry to see you leave Omafit — can we talk?",
      greeting: `Hi ${shopName} team,`,
      intro:
        "We noticed Omafit was uninstalled from your Shopify store. Before you move on, we'd like to understand what happened.",
      ask:
        "What led you to uninstall? Setup, virtual try-on results, pricing, or something else? Even a short reply helps a lot.",
      offer:
        "If it still makes sense, we're happy to talk and work through it together — sometimes it's a quick fix.",
      reply: "Just reply to this email. We're here to help.",
      signOff: "Thanks for trying Omafit,\nThe Omafit team",
    },
  }[locale];

  const text = [
    copy.greeting,
    "",
    copy.intro,
    "",
    copy.ask,
    "",
    copy.offer,
    "",
    copy.reply,
    "",
    copy.signOff,
    SUPPORT_EMAIL,
  ].join("\n");

  const html = `<!DOCTYPE html>
<html lang="${locale}">
  <body style="font-family: Inter, Arial, sans-serif; line-height: 1.6; color: #1f2937; max-width: 560px; margin: 0 auto; padding: 24px;">
    <p style="font-size: 18px; font-weight: 600;">${escapeHtml(copy.greeting)}</p>
    <p>${escapeHtml(copy.intro)}</p>
    <p>${escapeHtml(copy.ask)}</p>
    <p>${escapeHtml(copy.offer)}</p>
    <p>${escapeHtml(copy.reply)}</p>
    <p style="white-space: pre-line; color: #4b5563; margin-top: 28px;">${escapeHtml(copy.signOff)}</p>
    <p style="color: #6b7280; font-size: 14px;">${SUPPORT_EMAIL}</p>
  </body>
</html>`;

  return { subject: copy.subject, html, text };
}

export async function verifyShopifyWebhook(
  rawBody: string,
  hmacHeader: string | null,
  secret: string,
): Promise<boolean> {
  if (!hmacHeader) return false;

  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(rawBody));
  const computed = btoa(String.fromCharCode(...new Uint8Array(signature)));

  if (computed.length !== hmacHeader.length) return false;

  let mismatch = 0;
  for (let i = 0; i < computed.length; i++) {
    mismatch |= computed.charCodeAt(i) ^ hmacHeader.charCodeAt(i);
  }
  return mismatch === 0;
}

type ZohoTokenResponse = {
  access_token?: string;
  error?: string;
};

type ZohoSendResponse = {
  status?: { code?: number; description?: string };
  data?: { messageId?: string };
};

let cachedAccessToken: { token: string; expiresAt: number } | null = null;

function accountsBaseUrl(): string {
  return (Deno.env.get("ZOHO_ACCOUNTS_URL") ?? "https://accounts.zoho.com").replace(/\/$/, "");
}

function mailApiBaseUrl(): string {
  return (Deno.env.get("ZOHO_MAIL_API_URL") ?? "https://mail.zoho.com").replace(/\/$/, "");
}

async function refreshAccessToken(): Promise<string> {
  const clientId = Deno.env.get("ZOHO_CLIENT_ID")?.trim();
  const clientSecret = Deno.env.get("ZOHO_CLIENT_SECRET")?.trim();
  const refreshToken = Deno.env.get("ZOHO_REFRESH_TOKEN")?.trim();

  if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Missing ZOHO_CLIENT_ID, ZOHO_CLIENT_SECRET, or ZOHO_REFRESH_TOKEN");
  }

  const params = new URLSearchParams({
    refresh_token: refreshToken,
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: "refresh_token",
  });

  const response = await fetch(`${accountsBaseUrl()}/oauth/v2/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  });

  const payload = (await response.json()) as ZohoTokenResponse;
  if (!response.ok || !payload.access_token) {
    throw new Error(payload.error ?? `Zoho token refresh failed (${response.status})`);
  }

  cachedAccessToken = {
    token: payload.access_token,
    expiresAt: Date.now() + 50 * 60 * 1000,
  };

  return payload.access_token;
}

async function getAccessToken(): Promise<string> {
  if (cachedAccessToken && cachedAccessToken.expiresAt > Date.now()) {
    return cachedAccessToken.token;
  }
  return refreshAccessToken();
}

export type SendZohoEmailInput = {
  toAddress: string;
  subject: string;
  htmlContent: string;
  textContent: string;
  fromAddress?: string;
};

export async function sendZohoEmail(input: SendZohoEmailInput): Promise<string> {
  const accountId = Deno.env.get("ZOHO_ACCOUNT_ID")?.trim();
  const fromAddress = (input.fromAddress ?? Deno.env.get("ZOHO_FROM_ADDRESS") ?? "contato@omafit.co").trim();

  if (!accountId) {
    throw new Error("Missing ZOHO_ACCOUNT_ID");
  }

  const accessToken = await getAccessToken();
  const response = await fetch(`${mailApiBaseUrl()}/api/accounts/${accountId}/messages`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      Authorization: `Zoho-oauthtoken ${accessToken}`,
    },
    body: JSON.stringify({
      fromAddress,
      toAddress: input.toAddress,
      subject: input.subject,
      content: input.htmlContent,
      mailFormat: "html",
      askReceipt: "no",
    }),
  });

  const payload = (await response.json()) as ZohoSendResponse;
  if (!response.ok || payload.status?.code !== 200) {
    throw new Error(
      payload.status?.description ?? `Zoho Mail send failed (${response.status})`,
    );
  }

  return payload.data?.messageId ?? "sent";
}

export type WelcomeLocale = "pt" | "es" | "en";

const PORTUGUESE_COUNTRIES = new Set([
  "BR", "PT", "AO", "MZ", "CV", "GW", "ST", "TL",
]);

const SPANISH_COUNTRIES = new Set([
  "ES", "MX", "AR", "CO", "CL", "PE", "VE", "EC", "GT", "CU", "BO", "DO",
  "HN", "PY", "SV", "NI", "CR", "PA", "UY", "PR", "GQ",
]);

export function localeFromCountryCode(
  countryCode: string | null | undefined,
): WelcomeLocale {
  const code = (countryCode ?? "").trim().toUpperCase();
  if (!code) return "en";
  if (PORTUGUESE_COUNTRIES.has(code)) return "pt";
  if (SPANISH_COUNTRIES.has(code)) return "es";
  return "en";
}
